import sys
from collections import deque

MOD = 10**9 + 7

def bfs(graph, start):
    n = len(graph)
    dist = [-1] * n
    queue = deque([start])
    dist[start] = 0
    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

def diameter(graph):
    n = len(graph)
    if n == 0:
        return 0
    dist = bfs(graph, 0)
    farthest = dist.index(max(dist))
    dist = bfs(graph, farthest)
    return max(dist)

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    edges = [(int(data[2*i+1])-1, int(data[2*i+2])-1) for i in range(N-1)]

    graph = [[] for _ in range(N)]
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    total_sum = 0

    # Precompute diameters for all subtrees
    dp = [[0] * (1 << N) for _ in range(N)]
    for i in range(N):
        dp[i][1 << i] = diameter(graph)

    for mask in range(1, 1 << N):
        for i in range(N):
            if mask & (1 << i):
                submask = mask ^ (1 << i)
                dp[i][mask] = max(dp[i][submask], dp[i][mask])
                for j in range(N):
                    if submask & (1 << j):
                        dp[j][mask] = max(dp[j][submask], dp[j][mask])
                        dp[i][mask] = max(dp[i][mask], dp[j][submask] + 1)

    for mask in range(1, 1 << N):
        white_diameter = max(dp[i][mask] for i in range(N) if mask & (1 << i))
        black_diameter = max(dp[i][mask] for i in range(N) if not (mask & (1 << i)))
        total_sum += max(white_diameter, black_diameter)
        total_sum %= MOD

    print(total_sum)

