import sys
from collections import defaultdict

MOD = 10**9 + 7

def dfs(node, parent, graph, depth, max_depth):
    max_depth[node] = depth
    for neighbor in graph[node]:
        if neighbor != parent:
            dfs(neighbor, node, graph, depth + 1, max_depth)

def calculate_distances(n, edges):
    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    max_depth = [0] * (n + 1)
    dfs(1, -1, graph, 0, max_depth)

    distances = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in graph[i]:
            if max_depth[i] > max_depth[j]:
                distances[i][j] = 1
                distances[j][i] = 1
                dfs(j, i, graph, 1, max_depth)

    for k in range(1, n + 1):
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if distances[i][k] + distances[k][j] < distances[i][j]:
                    distances[i][j] = distances[i][k] + distances[k][j]

    return distances

def sum_of_niceness(n, edges):
    distances = calculate_distances(n, edges)
    total_sum = 0

    for mask in range(1 << n):
        max_white = 0
        max_black = 0
        for i in range(n):
            for j in range(i + 1, n):
                if (mask & (1 << i)) == (mask & (1 << j)):
                    if (mask & (1 << i)):
                        max_white = max(max_white, distances[i + 1][j + 1])
                    else:
                        max_black = max(max_black, distances[i + 1][j + 1])

        total_sum += max(max_white, max_black)
        total_sum %= MOD

    return total_sum

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    edges = []
    index = 1
    for _ in range(n - 1):
        a = int(data[index])
        b = int(data[index + 1])
        edges.append((a, b))
        index += 2

    result = sum_of_niceness(n, edges)
    print(result)

if __name__ == "__main__":
    main()
